import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"10. 主城弹射","description":"","frontmatter":{},"headers":[],"relativePath":"eject.md","filePath":"eject.md"}'),l={name:"eject.md"};function i(n,e,s,c,d,_){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_10-主城弹射" tabindex="-1">10. 主城弹射 <a class="header-anchor" href="#_10-主城弹射" aria-label="Permalink to &quot;10. 主城弹射&quot;">​</a></h1><h2 id="_10-1-用法" tabindex="-1">10.1 用法 <a class="header-anchor" href="#_10-1-用法" aria-label="Permalink to &quot;10.1 用法&quot;">​</a></h2><p>在主城输入 <code>/ej / /pej</code>。</p><h2 id="_10-2-效果" tabindex="-1">10.2 效果 <a class="header-anchor" href="#_10-2-效果" aria-label="Permalink to &quot;10.2 效果&quot;">​</a></h2><ol><li>5 秒倒计时。</li><li>把你弹射到高空（约 <strong>y=319</strong>，接近世界高度上限）。</li><li>落点在主世界以 <code>(0,0)</code> 为圆心、<strong>半径 1000 格</strong>的圆内随机选择。</li><li>从弹射那一刻起给你 <strong>20 秒摔落保护</strong>；正常落地会消耗掉这次保护，并在落地处播放一圈粒子与爆炸音效，同时显示 <code>Boom~</code>。</li></ol><h2 id="_10-3-注意" tabindex="-1">10.3 注意 <a class="header-anchor" href="#_10-3-注意" aria-label="Permalink to &quot;10.3 注意&quot;">​</a></h2><ul><li>只能在主城使用；在主世界、下界、末地输入会被拒绝。</li><li>落点是随机安全点，但服务器只保证“尽量安全”，不保证落点周围没有怪、岩浆或悬崖。</li><li><strong>摔落保护不是“落地后再给 20 秒”</strong>：它从弹射瞬间开始计时，共 20 秒，用来兜住这一跳；落地时就被用掉，所以<strong>落地之后再跳崖照常摔伤</strong>。若这一跳没造成摔落伤害（例如落进水里），保护不会被消耗，会保留到 20 秒结束。其他伤害（怪物、岩浆、窒息）全程照常。</li><li>建议落地前看清坐标（Java 版按 F3，基岩版打开坐标显示），落地后立刻 <code>/sethome</code> 或记坐标。</li></ul>',7)])])}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
